using Servicio.RetazoMarket.Business.DTOs.Personalizacion;using Servicio.RetazoMarket.DataManagment.Models;
namespace Servicio.RetazoMarket.Business.Mappers;public static class PersonalizacionBusinessMapper {public static PersonalizacionDataModel ToDataModel(CrearPersonalizacionRequest r)=>new(){id_producto=r.id_producto,nombre_atr=r.nombre_atr.Trim(),tipo_valor=r.tipo_valor.Trim().ToUpperInvariant(),valores_json=r.valores_json.Clone(),costo_adicional=r.costo_adicional};public static PersonalizacionDataModel ToDataModel(ActualizarPersonalizacionRequest r)=>new(){id_opcion=r.id_opcion,id_producto=r.id_producto,nombre_atr=r.nombre_atr.Trim(),tipo_valor=r.tipo_valor.Trim().ToUpperInvariant(),valores_json=r.valores_json.Clone(),costo_adicional=r.costo_adicional};public static PersonalizacionResponse ToResponse(PersonalizacionDataModel m)=>new(){id_opcion=m.id_opcion,id_producto=m.id_producto,nombre_atr=m.nombre_atr,tipo_valor=m.tipo_valor,valores_json=m.valores_json.Clone(),costo_adicional=m.costo_adicional};}
